"""Original beginner textbook and exercises; never labelled as past exam questions."""
import json
from pathlib import Path
root=Path(__file__).parent
data=json.loads((root/'content.json').read_text())
books={}

def chapter(i,terms,sections,bridge):
    books[i]=dict(terms=[dict(word=w,meaning=m) for w,m in terms],sections=[dict(title=t,paragraphs=p.split('\n')) for t,p in sections],bridge=bridge)

chapter(1,[('회계','회사에서 일어난 경제적 일을 돈의 금액으로 기록하고 정리해 정보를 만드는 일.'),('자산','회사가 통제하는 경제적 자원. 현금, 기계, 받을 돈 등이 있어.'),('부채','회사가 자원을 넘겨 이행해야 하는 현재의무. 빌린 돈, 지급할 돈 등이 있어.'),('자본','자산에서 부채를 뺀 나머지 몫. 주주가 낸 돈과 쌓인 이익 등이 포함돼.')],[
('회계는 무엇을 기록할까?','카페를 열었다고 생각해보자. 통장에 돈을 넣고, 커피 머신을 사고, 커피를 팔게 될 거야. 이런 일을 기억에만 맡기면 얼마가 남았는지, 얼마를 갚아야 하는지 알기 어려워. 회계는 이 경제적 사건들을 일정한 규칙에 따라 기록하고 정리하는 일이야.\n여기서는 카페와 주인을 구분해서 볼 거야. 주인의 개인 통장이 아니라 카페가 가진 것과 카페의 의무를 기록한다고 생각하면 돼. 주인이 회사에 돈을 넣는 일도 회사 입장에서는 기록할 거래야.'),
('자산은 현금보다 넓은 말이야','자산에는 현금뿐 아니라 보통예금, 커피 머신, 판매할 원두, 손님에게 받을 돈도 들어갈 수 있어. 서로 모습은 다르지만 회사에 경제적 이익을 줄 수 있는 자원이라는 공통점이 있어. 단순히 소중하다고 느끼는 모든 것을 장부에 자산으로 적는 건 아니고, 통제와 인식 요건을 판단해야 해.\n기초 문제에서는 먼저 현금과 기계를 구분해보면 돼. 현금 500만 원 중 200만 원으로 기계를 사면 현금은 300만 원, 기계는 200만 원이야. 전체 자산은 300 + 200 = 500만 원으로 그대로야. 돈이 없어졌다고 생각하기 전에 무엇으로 바뀌었는지를 봐.'),
('빌린 돈은 자산일까, 부채일까?','은행에서 빌린 100만 원이 카페 통장에 들어왔다면, 통장에 보유한 돈은 자산이야. 동시에 카페에는 은행에 100만 원을 갚아야 할 의무가 생겨. 이 의무를 부채라고 해. 하나의 대출 거래가 자산과 부채를 함께 늘린 거야.\n따라서 “빌린 돈이니까 자산에 넣지 않는다”는 생각은 틀려. 반대로 통장에 입금됐다고 모두 매출수익인 것도 아니야. 대출은 갚을 의무를 만들고, 수익은 소유주의 출자와 구분되는 성과라는 점이 달라.'),
('자본은 자산에서 빚을 뺀 몫이야','내가 낸 돈 400만 원과 은행 대출 100만 원으로 시작했다면 카페 자산은 500만 원이야. 이 중 은행에 갚아야 할 100만 원을 제외한 400만 원이 자본이지. 자본은 통장 안의 별도 현금 꾸러미가 아니라 자산에서 부채를 뺀 잔여 몫을 뜻해.\n이 관계를 자산 = 부채 + 자본이라고 써. 500 = 100 + 400이 되는 거야. 자산과 부채를 알면 자본을 빼기로 구할 수 있고, 자산과 자본을 알면 부채를 구할 수 있어. 식부터 외우기보다 가진 것 전체를 빚과 내 몫으로 나눠 보는 관계를 먼저 이해해.'),
('거래 전과 후를 비교해보자','현금 500, 기계 0, 부채 100, 자본 400에서 출발하자. 단위는 만 원이야. 현금 200으로 기계를 사면 현금 300, 기계 200, 부채 100, 자본 400이 돼. 자산의 구성만 바뀌었어.\n이어서 현금 100으로 대출을 갚으면 현금 200, 기계 200, 부채 0, 자본 400이야. 총자산과 부채가 각각 100씩 줄었지. 원금을 갚는 일 자체는 비용이 아니야. 이자까지 지급했다면 원금 상환과 이자비용은 나눠서 생각해야 해.')],
'기출에서 “기말자본”, “총자산”, “차입”, “상환”이 나오면 먼저 자산·부채·자본 중 무엇이 늘고 줄었는지 적어봐. 차입은 빌리는 것, 상환은 갚는 것이야.')

chapter(2,[('계정과목','현금, 차입금, 임차료처럼 같은 성격의 거래를 모아 기록하는 이름.'),('차변','분개의 왼쪽 자리. 자산 증가와 비용 발생 등을 기록하는 쪽.'),('대변','분개의 오른쪽 자리. 부채·자본 증가와 수익 발생 등을 기록하는 쪽.'),('분개','하나의 거래를 계정과목과 금액으로 나눠 차변과 대변에 적는 것.')],[
('이름표를 붙여서 기록해','돈이 늘거나 줄었다는 말만으로는 거래의 성격을 알기 어려워. 상품을 팔아서 들어온 돈인지, 빌려서 들어온 돈인지 구분해야 하거든. 그래서 회계는 비슷한 항목에 같은 이름표를 붙여 기록해. 이 이름이 계정과목이야.\n예를 들어 손에 가진 돈은 현금, 은행에 맡겨 둔 돈은 보통예금, 빌려서 갚아야 할 돈은 차입금이라는 이름을 쓸 수 있어. 이 책의 단순 예제는 현금으로 통일하는 경우가 있지만, 시험에서는 현금과 보통예금을 구분하라는 조건을 읽어야 해.'),
('차변과 대변은 자리 이름이야','차변은 왼쪽, 대변은 오른쪽이야. 차변을 돈이 들어오는 쪽, 대변을 돈이 나가는 쪽으로만 외우면 비용이나 부채에서 곧 막히게 돼. 먼저 어떤 계정인지 보고, 그 계정이 늘었는지 줄었는지를 판단해야 해.\n자산은 늘면 차변, 줄면 대변에 적어. 부채와 자본은 늘면 대변, 줄면 차변이야. 비용은 발생하면 차변, 수익은 발생하면 대변에 기록해. 이 기본 규칙은 자산 = 부채 + 자본 관계와 연결돼 있어.'),
('분개는 네 가지 질문으로 풀어','첫째, 무슨 일이 생겼는지 읽어. 둘째, 바뀐 항목의 계정과목을 찾아. 셋째, 각각 증가인지 감소인지 표시해. 넷째, 각 항목의 규칙에 맞춰 차변과 대변에 놓으면 돼.\n현금 50만 원을 빌렸다면 현금이라는 자산이 증가하고 차입금이라는 부채가 증가해. 그래서 (차) 현금 50 / (대) 차입금 50이야. 괄호 속 차와 대는 차변과 대변의 줄임말이고, 숫자 단위는 문제에서 정한 단위를 따라.'),
('비용을 낼 때와 빚을 갚을 때','월세 20만 원을 현금으로 냈다면 (차) 임차료 20 / (대) 현금 20이야. 임차료라는 비용이 발생하고 현금 자산은 줄었기 때문이지.\n차입금 원금 20만 원을 갚았다면 (차) 차입금 20 / (대) 현금 20이야. 현금이 줄었다는 점은 같지만, 차변이 비용이 아니라 부채 감소라는 점이 달라. “돈을 썼다”는 사실보다 무엇 때문에 지급했는지를 구분해.'),
('두 쪽 금액을 꼭 맞춰','하나의 분개에서 차변 합계와 대변 합계는 반드시 같아야 해. 차변에 현금 60과 기계 40이 있다면 대변 합계는 100이어야 해. 이처럼 두 측면을 함께 기록하는 구조가 복식부기야.\n금액이 같다는 사실만으로 분개가 모두 맞는 건 아니야. 계정과목이나 기록 방향이 잘못돼도 합계는 같을 수 있어. 따라서 거래 해석, 계정 성격, 증감, 양쪽 합계 순서로 확인해야 해.')],
'기출의 “옳은 분개”는 현금 움직임만 보지 말고 반대편 계정을 찾아. 외상대금 회수는 받을 돈을 현금으로 바꾸는 거래라, 이미 기록한 매출을 또 기록하지 않아.')

chapter(3,[('발생기준','현금 수수만이 아니라 거래의 효과가 실제 발생한 기간에 수익·비용을 인식하는 기준.'),('선급비용','미리 지급했지만 아직 사용하지 않아 미래 기간의 효익이 남은 비용 성격의 자산.'),('선수수익','대금을 먼저 받았지만 서비스 제공 등 의무를 아직 이행하지 않은 부분의 부채.'),('미지급비용','이미 발생한 비용 중 아직 지급하지 않은 부분의 부채.')],[
('현금의 날짜와 성과의 날짜','12월에 일을 끝내고 대금은 1월에 받았다고 생각해봐. 일을 한 시점은 12월이고 돈을 받은 시점은 1월이야. 발생기준은 현금을 받았는지만 보지 않고 실제 성과와 의무가 언제 발생했는지를 따져.\n서비스를 완료해 수익 인식 요건을 충족했다면 12월 수익으로 기록하고, 아직 받지 못한 금액은 받을 권리인 자산으로 잡아. 일반적인 미수수익과 고객계약의 매출채권·계약자산은 거래 조건에 따라 구분하므로 문제에 제시된 계정을 따라야 해.'),
('먼저 낸 보험료를 나눠보자','보험료를 1년치 한꺼번에 냈다고 해서 항상 전액이 지급한 달의 비용이 되는 건 아니야. 결산일 현재 사용한 기간은 당기 비용, 아직 사용하지 않은 기간은 자산인 선급비용으로 구분해.\n10월 1일에 1년 보험료 120만 원을 지급하고 12월 31일에 결산한다고 하자. 월 10만 원 중 10·11·12월의 3개월분 30만 원이 당기 비용이야. 나머지 9개월분 90만 원은 다음 기간에 받을 효익이므로 선급비용으로 남아.'),
('먼저 받은 대금과 아직 안 낸 급여','고객이 다음 달 서비스 대금을 먼저 줬다면 지금 당장 모든 수익이 완성된 건 아니야. 앞으로 서비스를 제공할 의무가 남아 있어. 이 미이행 부분은 선수수익 또는 계약부채처럼 부채로 기록하고, 실제로 제공한 부분만 수익으로 옮겨.\n반대로 종업원이 이번 달에 일했지만 급여를 다음 달에 준다면, 이번 달의 급여비용과 미지급 의무를 기록해. 지급을 미뤘다고 이번 달 비용이 사라지는 건 아니야.'),
('결산 조정은 기간을 맞추는 일','결산은 회계기간 말에 장부를 정리해 그 기간의 상태와 성과를 확정하는 과정이야. 이때 선급·선수·미수·미지급 등을 조정해 빠진 수익과 비용을 반영해.\n순이익은 수익에서 비용을 뺀 금액이야. 수익 800, 비용 550이면 순이익은 250이지. 소유주의 출자와 배당은 수익·비용이 아니라 자본거래로 구분하므로 이 계산에 섞지 않아.')],
'“당기”는 지금 계산하는 회계기간, “전기”는 그 전 기간, “차기”는 다음 기간이야. 결산문제에서는 돈을 낸 날과 사용한 기간에 각각 밑줄을 그어봐.')

chapter(4,[('매출채권','통상 영업에서 상품이나 서비스를 판매하고 받을 대가에 대한 채권.'),('손실충당금','채권에서 회수하지 못할 것으로 예상되는 신용손실을 반영하는 차감 항목.'),('순장부금액','자산의 장부상 총액에서 관련 차감 항목을 뺀 금액.'),('현금성자산','단기 현금수요 충족을 위해 보유하며 현금 전환이 쉽고 가치변동 위험이 매우 작은 투자.')],[
('받을 돈도 자산이야','물건을 외상으로 팔면 지금 현금은 받지 않았지만 대금을 받을 권리가 생겨. 이를 매출채권이라고 해. 외상매출금과 받을어음처럼 더 세부적인 계정으로 나눌 수도 있어. 외상매입 후 지급할 돈인 매입채무와 반대 방향이라는 점을 구분해.\n나중에 대금을 현금으로 받으면 현금이 늘고 매출채권이 줄어. 이미 판매 때 기록한 수익을 회수 때 다시 기록하면 매출을 두 번 세는 오류가 생겨.'),
('받을 돈을 전부 받을 수 있을까?','거래처가 어려워져 대금을 못 받을 위험이 있다면, 받을 돈 총액을 그대로 회수가능 금액으로 보는 것은 적절하지 않을 수 있어. 이 위험에 대한 기대신용손실을 손실충당금으로 반영해. 기초 교재에서는 대손충당금이라는 표현도 만나게 돼.\n예를 들어 채권 총액 500만 원, 충당금 20만 원이면 순장부금액은 480만 원이야. 충당금은 채권에서 차감하는 평가 항목이지, 실제로 따로 쌓아둔 현금이 아니야.'),
('필요 잔액과 추가 비용을 구분해','결산일에 필요한 충당금이 30만 원이고 이미 대변에 10만 원 남아 있다면 추가로 설정할 금액은 20만 원이야. 30만 원을 다시 전부 더하면 충당금이 40만 원이 되어 목표보다 커져.\n문제에서 실제 대손처리나 상각채권 회수가 있었다면 그 거래를 먼저 반영한 뒤 조정 전 잔액을 구해야 해. 단순히 기초잔액만 빼는 문제가 아닐 수도 있으므로 기간 중 변동을 먼저 읽어.'),
('현금과 현금성자산을 구분해','현금성자산은 현금 그 자체는 아니지만 단기 현금수요를 충족하기 위해 보유하는, 현금 전환이 쉽고 가치변동 위험이 매우 작은 투자야. 일반적으로 취득일부터 만기까지가 3개월 이내인지 살펴봐.\n만기가 짧다는 조건만으로 충분하지는 않아. 위험과 전환가능성도 함께 충족해야 하고, 주가 변동이 큰 보통주를 단기 보유했다는 이유만으로 현금성자산이라고 할 수는 없어.')],
'채권평가 문제는 ① 결산 전 충당금 잔액 ② 결산에 필요한 잔액 ③ 둘의 차이 순서로 계산해. “대손 확정”과 “대손 추정”도 나눠 읽어.')

chapter(5,[('재고자산','판매하거나 생산에 사용하기 위해 보유하는 상품·제품·재료 등의 자산.'),('매출원가','판매된 상품이나 제품에 대응하는 원가.'),('순실현가능가치','통상 영업의 예상 판매가에서 완성과 판매에 필요한 원가를 뺀 금액.'),('선입선출법','먼저 들어온 재고의 원가가 먼저 판매된 것으로 보고 원가를 배분하는 방법.')],[
('물건을 살 때와 팔 때','판매용 상품을 샀다면 아직 팔지 않은 부분은 재고자산이야. 구입할 때 현금이 나갔다고 해서 전액을 바로 당기 비용으로 보는 것은 아니야. 판매된 부분의 원가를 매출원가로 옮기고, 남은 부분을 재고자산으로 남겨.\n판매가격과 원가는 서로 달라. 원가 3만 원인 상품을 5만 원에 팔면 매출은 5만 원, 매출원가는 3만 원이야. 판매 활동의 다른 비용을 빼기 전 차액 2만 원이 매출총이익이 돼.'),
('재고 수불 관계를 식으로 써','처음 있던 재고에 새로 산 재고를 더하면 팔거나 보유할 수 있는 전체 원가가 돼. 여기서 마지막에 남은 재고를 빼면 판매된 부분을 구할 수 있어. 그래서 매출원가 = 기초재고 + 순매입액 − 기말재고야.\n기초 100, 순매입 500, 기말 150이면 600 중 150이 남고 450이 판매원가가 된 거야. 매입운임은 재고를 현재 장소로 가져오는 원가에 포함하고, 매입환출은 되돌려 보낸 물건의 금액이므로 빼.'),
('같은 상품을 다른 가격에 샀다면','10개를 개당 1,000원, 나중에 10개를 개당 1,200원에 샀다고 하자. 12개를 팔았을 때 선입선출법은 먼저 산 10개와 나중에 산 2개의 원가를 판매원가로 배분해. 10×1,000 + 2×1,200 = 12,400원이야.\n평균법은 평균단가로 배분하는 방법이야. 모든 매입 뒤 판매했다면 총원가 22,000원을 20개로 나눈 1,100원이 단가가 되고, 12개 원가는 13,200원이 돼. 매입·판매 시점이 여러 번이면 이동평균법과 총평균법의 차이도 따져야 해.'),
('남은 재고의 가치가 내려가면','재고는 원가와 순실현가능가치 중 낮은 금액으로 평가해. 원가 80만 원인 재고를 완성·판매하는 데 필요한 비용을 뺀 회수 예상액이 70만 원이라면 70만 원으로 낮춰 평가하는 거야.\n기말재고를 실제보다 크게 적으면 매출원가는 작아지고 당기이익은 커져. 재고 오류 문제는 매출원가 식에서 기말재고 앞이 빼기라는 점으로 방향을 판단하면 돼.')],
'“기초·기말”, “환출”, “운임”, “선입선출”, “평균”에 표시해. 단가 계산 문제는 먼저 수량과 금액을 다른 줄에 적어봐.')

chapter(6,[('취득원가','자산을 취득해 의도한 장소와 사용 상태에 이르게 하는 데 드는 원가.'),('잔존가치','내용연수가 끝났다고 가정할 때 예상 처분대가에서 처분원가를 뺀 금액.'),('내용연수','자산을 사용할 것으로 예상되는 기간 또는 생산량 등의 사용 단위.'),('감가상각','상각대상금액을 내용연수에 걸쳐 체계적으로 비용에 배분하는 것.')],[
('오래 쓰는 기계는 비용도 나눠','커피 머신을 여러 해 사용한다면 구입금액을 언제 비용으로 반영할지 정해야 해. 감가상각은 기계의 상각대상금액을 사용기간에 나눠 배분하는 과정이야. 기계 가격을 매년 시세로 바꿔 적는 것과는 달라.\n기계를 사용할 수 있게 하는 설치비 등은 취득원가에 들어갈 수 있어. 일상적인 수선비는 보통 당기 비용이지만, 후속 지출이 자산 인식 요건을 충족하는 경우에는 자산에 포함할 수 있으므로 문제의 조건을 읽어.'),
('정액법 공식을 풀어서 이해해','취득원가에서 마지막에 남을 잔존가치를 빼면 사용기간에 나눌 금액이 돼. 이 금액을 내용연수로 균등하게 나누는 방법이 정액법이야. 연간 상각비 = (취득원가 − 잔존가치) ÷ 내용연수로 계산해.\n취득원가 500, 잔존가치 50, 내용연수 5년이면 450을 5년에 나누므로 연간 90이야. 연중 사용을 시작했고 월할 계산을 요구하면 사용가능 상태가 된 뒤의 사용월수도 반영해.'),
('장부금액과 처분손익','감가상각누계액은 지금까지 누적한 상각금액이야. 원가에서 누계액 등을 차감한 장부금액과 실제 처분대가를 비교하면 처분손익을 구할 수 있어.\n취득원가 600, 누적 상각 240이면 다른 조정이 없을 때 장부금액 360이야. 처분대가가 400이면 40의 처분이익이 돼. 처분일까지 추가로 상각해야 하는 금액이 있는지도 확인해.'),
('토지·무형자산·투자부동산','토지는 일반적으로 내용연수에 제한이 없어 감가상각하지 않아. 특허권처럼 물리적 형체가 없는 식별가능 자산은 무형자산이야. 연구단계 지출은 비용 처리하고, 개발단계는 여러 인식 요건을 모두 충족해야 자산으로 기록할 수 있어.\n내용연수가 비한정인 무형자산은 상각하지 않고 정기적으로 손상검토를 해. 임대수익이나 시세차익을 얻기 위해 보유한 부동산은 투자부동산으로 구분할 수 있어. 회사가 직접 쓰는 부동산이나 통상 판매용 부동산과 목적이 달라.')],
'상각 문제는 ① 취득원가 ② 잔존가치 ③ 내용연수 ④ 사용기간 순으로 적어. 처분 문제는 처분 시점까지 상각한 뒤 장부금액을 비교해.')

chapter(7,[('금융자산','현금, 다른 기업의 지분상품, 현금을 받을 계약상 권리 등에 해당하는 자산.'),('현재가치','미래 현금흐름을 적절한 할인율로 현재 시점의 금액으로 환산한 값.'),('할인율','미래 금액을 현재가치로 바꿀 때 적용하는 이자율 성격의 비율.'),('유효이자율','예상 미래 현금흐름을 금융상품의 현재 장부금액에 일치시키는 이자율.')],[
('기계와 다른 회사 주식의 차이','기계는 회사가 영업에 사용하는 실물자산이지만, 다른 회사의 주식은 지분상품으로서 금융자산이 될 수 있어. 외상매출금처럼 계약에 따라 돈을 받을 권리도 금융자산에 포함돼.\n금융자산이라는 이름만 보고 모두 같은 방식으로 평가하지는 않아. 어떤 목적으로 보유하는지와 계약상 현금흐름의 특성에 따라 적용 분류와 측정 방식이 달라져.'),
('오늘 100과 내년 100은 달라','오늘 받은 돈은 이자를 얻거나 다른 곳에 사용할 수 있어. 그래서 미래에 받을 금액을 평가할 때는 시간가치를 반영해 현재 시점의 금액으로 환산할 수 있어. 이 값이 현재가치야.\n1년 뒤 110만 원을 받을 때 할인율이 10%라면 현재가치는 110 ÷ 1.1 = 100만 원이야. 현재 100을 10%로 운용하면 1년 뒤 110이 된다는 관계를 거꾸로 계산한 거지.'),
('기간이 늘어나면 나누기를 반복해','2년 뒤 121만 원을 받고 매년 할인율이 10%라면 121 ÷ 1.1 ÷ 1.1 = 100만 원이야. 원금과 기간이 같은 경우 할인율이 높을수록 현재가치는 작아져.\n여러 해의 이자를 받는 금융상품은 각 시점의 현금흐름을 할인한 값을 합쳐야 해. 시험에서 현재가치계수를 주면 현금흐름의 성격에 맞는 계수를 곱하고, 한 번 받는 원금과 반복해서 받는 이자를 구분해.'),
('평가 방식과 이자수익','당기손익-공정가치 측정 금융자산은 공정가치 변동을 당기손익에 반영하는 분류야. 장부금액 100인 주식이 결산일에 120이고 다른 변동이 없다면 평가이익 20을 인식해. 이 분류의 취득 거래원가는 일반적으로 즉시 비용 처리해.\n상각후원가 분류는 보유 사업모형과 원금·이자만으로 구성된 계약상 현금흐름 요건 등을 함께 판단해. 유효이자수익 계산에서는 기초 장부금액에 유효이자율을 곱해. 단순 표시이자와 혼동하지 않는 것이 중요해.')],
'영어 약어 FVTPL은 당기손익-공정가치 측정을 뜻해. 문제에 제시된 분류부터 확인한 다음 평가손익인지 이자수익인지 나눠 계산해.')

chapter(8,[('사채','회사가 채권자에게 발행하는 채무증권. 주식과 달리 계약상 원리금 지급 의무가 생겨.'),('액면금액','사채에 표시된 기준 금액으로, 일반적으로 만기에 상환할 원금의 기준.'),('표시이자율','액면금액을 기준으로 현금이자를 정할 때 적용하는 약정 이자율.'),('할인발행','발행금액이 액면금액보다 낮은 발행 방식.')],[
('사채는 회사가 빌리는 방법이야','회사는 은행에서 대출받는 것 외에 사채를 발행해 자금을 빌릴 수 있어. 투자자에게 채무증권을 발행하고 약정에 따라 이자와 원금을 지급하는 구조야. 돈을 받았다는 사실은 같아도 주주가 출자하는 주식 발행과는 부채·자본 분류가 달라.\n액면금액은 만기 원금의 기준이고, 발행금액은 투자자가 처음 실제로 낸 대가야. 시장이 요구하는 수익률에 따라 둘이 다를 수 있어. 발행금액이 작으면 할인발행, 크면 할증발행이야.'),
('현금이자와 비용은 다를 수 있어','현금이자는 보통 액면금액 × 표시이자율로 계산해. 액면 100, 표시이자율 6%이면 연간 현금이자는 6이야. 그러나 장부에 반영하는 유효이자비용은 기초 장부금액 × 유효이자율로 계산해.\n할인발행 사채의 기초 장부금액 90, 유효이자율 10%이면 비용은 9야. 현금 지급 6과 비용 9의 차이 3은 할인액 상각으로 연결돼. 단위와 이자 지급 주기는 반드시 문제 조건을 따라.'),
('사채 장부금액이 변하는 이유','앞 예에서 장부금액은 90에서 93으로 증가해. 현금으로 지급한 이자보다 비용이 3 더 컸기 때문에 할인발행한 차액의 일부를 상각한 거야. 할인사채 장부금액은 만기에 가까워질수록 액면금액에 접근해.\n할증발행 사채에서는 일반적으로 현금이자가 유효이자비용보다 커서 장부금액이 감소하는 방향이 돼. 방향을 먼저 판단한 뒤 계산하면 더하거나 빼는 실수를 줄일 수 있어.'),
('부채의 다른 이름도 알아두자','외상매입의 지급 의무는 매입채무, 비용 발생 후 아직 지급하지 않은 의무는 미지급비용처럼 원인에 따라 이름을 달리해. 부채라고 모두 차입금으로 적는 것은 아니야.\n충당부채는 과거 사건에 따른 현재의무가 있고, 자원 유출 가능성이 높으며, 금액을 신뢰성 있게 추정할 수 있는지 등을 판단해 인식해. 단순한 미래 계획만으로 현재 부채가 생기는 것은 아니야.')],
'사채 문제의 첫 줄에 액면·발행금액·표시이자율·유효이자율을 따로 적어. 현금이자와 유효이자비용을 계산할 기준 금액이 서로 다르기 때문이야.')

chapter(9,[('자본금','주식 발행 등에 따라 법정 자본으로 기록하는 금액. 액면주식은 보통 액면금액을 기준으로 해.'),('주식발행초과금','주식의 발행금액이 자본금에 해당하는 액면금액을 초과하는 부분.'),('자기주식','회사가 다시 취득해 보유한 자기 회사 주식으로, 자본에서 차감하는 항목.'),('기본주당이익','보통주 귀속 이익을 가중평균 유통보통주식수로 나눈 주당 성과.')],[
('주주가 낸 돈을 나눠 기록해','액면 5,000원인 주식을 8,000원에 100주 발행하면 회사에 현금 80만 원이 들어와. 이때 자본금은 5,000×100 = 50만 원이고, 그보다 더 받은 30만 원은 주식발행초과금이야.\n주주가 낸 돈은 영업으로 번 매출이 아니므로 매출수익으로 기록하지 않아. 같은 자본 증가여도 법정 자본과 자본잉여금 등 성격에 따라 계정을 나눠.'),
('이익잉여금과 배당','회사가 이익을 내고 분배하지 않은 부분을 쌓아 두면 이익잉여금이 늘 수 있어. 기초 이익잉여금 200, 당기순이익 70, 현금배당 20이고 다른 변동이 없으면 기말은 250이야.\n배당은 주주에게 이익을 분배하는 것이므로 급여나 임차료 같은 비용이 아니야. 현금이 나갔다고 모두 손익계산서 비용으로 넣는 실수를 피해야 해.'),
('자기주식은 다른 회사 주식과 달라','다른 회사의 주식을 산 경우는 금융자산이 될 수 있지만, 자기 회사 주식을 다시 사 온 경우에는 자산이 아니라 자본을 차감해. 회사와 소유주 사이의 지분거래로 보기 때문이야.\n현금 40만 원으로 자기주식을 취득하면 현금 자산과 자본이 각각 40만 원 줄어. 자기주식 재발행·처분 차액도 일반적인 주식 투자손익과 동일하게 생각하면 안 돼.'),
('주당이익에서 기간을 반영해','기본주당이익은 보통주에 귀속되는 당기이익을 가중평균 유통보통주식수로 나눈 값이야. 우선주배당 등 조정이 주어지면 분자에서 적절히 반영해야 해.\n1월부터 1,000주가 있었고 7월 1일 현금 발행으로 1,000주가 추가됐다면, 기존 주식은 1년 전체, 새 주식은 반년 동안 유통됐어. 가중평균은 1,000 + 1,000×6/12 = 1,500주야. 무상증자·주식분할은 별도 조정이 필요하므로 현금 발행과 구분해.')],
'자본 문제는 현금 유입 전체와 자본금만을 구분해. 주당이익에서는 주식수만 세지 말고 몇 개월 유통됐는지도 표시해.')

chapter(10,[('재무상태표','특정 시점의 자산·부채·자본을 표시하는 재무제표.'),('손익계산서','일정 기간의 수익·비용과 성과를 보여주는 재무제표.'),('영업활동','기업의 주된 수익창출 활동 및 투자·재무활동이 아닌 기타 활동.'),('투자활동','장기성 자산과 현금성자산이 아닌 기타 투자의 취득·처분 활동.')],[
('사진과 기간 기록의 차이','재무상태표는 12월 31일처럼 특정 시점의 상태를 보여주는 사진이라고 생각하면 돼. 가진 자산, 이행할 부채, 남은 자본을 담아. 반면 손익계산서는 1월부터 12월까지처럼 일정 기간에 생긴 수익과 비용을 모아 보여줘.\n이 둘을 연결하면 이익이 자본에 어떻게 쌓였는지 이해할 수 있어. 다만 자본에는 소유주의 출자·배당과 기타포괄손익 등 다른 변동도 있으므로 순이익만으로 모든 자본 변동을 설명할 수는 없어.'),
('매출총이익과 영업이익','상품을 판 매출에서 그 상품의 매출원가를 빼면 매출총이익이야. 여기에서 판매와 관리에 쓴 비용 등을 반영하면 영업이익을 계산할 수 있어. 초급 문제에서는 주어진 항목 범위를 먼저 확인해.\n매출 1,000, 매출원가 600, 판매관리비 150이고 다른 영업손익이 없으면 매출총이익은 400, 영업이익은 250이야. 각각 계산하는 단계가 다르므로 문제에서 어떤 이익을 물었는지 다시 읽어.'),
('이익은 현금 잔액이 아니야','외상 판매는 수익을 만들지만 현금은 나중에 들어올 수 있어. 감가상각비는 이익을 줄이지만 그 상각을 기록하는 순간에 현금을 지급하는 것은 아니지. 따라서 손익과 현금흐름은 같지 않아.\n현금흐름표는 영업·투자·재무활동으로 현금흐름을 구분해 보여줘. 일반적인 기계 취득은 투자활동, 차입금 조달은 재무활동이야. 이자·배당 등은 적용 기준과 조건에 따른 분류도 확인해야 해.'),
('간접법 조정의 이유','영업현금흐름을 간접법으로 구할 때는 이익에서 출발해 현금과 다르게 반영된 부분을 조정해. 이익에서 이미 차감했지만 현금유출이 아닌 감가상각비는 다시 더해. 받을 돈이 늘어난 부분은 아직 현금으로 받지 못했으므로 일반적으로 차감해.\n순이익 100, 감가상각비 20, 매출채권 증가 10이고 다른 조정이 없으면 100+20−10=110이야. 조정 항목의 방향을 그냥 외우기보다 현금이 실제로 들어오거나 나갔는지 연결해보자.')],
'재무제표 문제는 시점인지 기간인지, 현금인지 이익인지 먼저 나눠. “간접법”이 나오면 비현금 항목과 영업 관련 자산·부채 변동을 순서대로 조정해.')

chapter(11,[('직접재료원가','특정 제품에 직접 추적할 수 있는 주요 재료의 소비 원가.'),('직접노무원가','제품 제조에 직접 사용한 노동에 대해 해당 제품에 추적하는 원가.'),('제조간접원가','제조원가 중 특정 제품에 직접 추적하지 않는 공통 원가.'),('가공원가','직접노무원가와 제조간접원가를 합한 원가.')],[
('원가는 무엇을 위해 썼는지 봐','카페에서 빵을 만든다고 하자. 밀가루, 제빵사의 작업, 공장 오븐 전기료가 모두 빵 생산에 필요해. 원가회계는 이런 자원이 제품에 얼마나 사용됐는지 계산하는 분야야. 재무회계의 자산·비용 구분과 연결되지만 제품별·공정별 원가를 더 자세히 살펴봐.\n먼저 제조에 든 원가와 판매·관리에 든 비용을 구분해. 공장 비용이라고 무조건 직접원가는 아니고, 제조와 무관한 본사 광고비나 판매사원 급여는 일반적으로 제조원가에 넣지 않아.'),
('제조원가의 세 요소','특정 제품에 직접 추적되는 주요 재료는 직접재료원가야. 특정 제품을 조립하는 작업자의 직접 작업임금은 직접노무원가가 될 수 있어. 공장 임차료·공장 감가상각비처럼 여러 제품에 공통으로 드는 제조원가는 제조간접원가로 묶어.\n직접과 간접의 구분은 어떤 대상을 원가 계산의 단위로 삼는지, 경제적으로 추적할 수 있는지와 관련돼. 제품에 바로 연결할 수 없거나 직접 추적하지 않는 소액 보조재료 등도 제조간접원가에 포함할 수 있어.'),
('기본원가와 가공원가','제조원가는 직접재료+직접노무+제조간접의 합계야. 이 중 직접재료와 직접노무를 합한 것을 기본원가, 직접노무와 제조간접을 합한 것을 가공원가라고 해. 가공은 재료를 제품으로 바꾸는 작업이라고 이해하면 돼.\n재료 100, 노무 60, 제조간접 40이면 제조원가 200, 기본원가 160, 가공원가 100이야. 기본원가와 가공원가를 다시 합하면 직접노무 60이 두 번 들어가므로 제조원가와 같지 않아.'),
('제품원가는 언제 비용이 될까?','아직 판매되지 않은 제품원가는 재공품이나 제품 같은 재고자산에 남을 수 있어. 팔린 제품에 대응하는 부분이 매출원가로 이동해. 제품을 만들면서 자원을 사용한 때와 판매원가로 인식되는 때를 구분하는 거야.\n본사 광고비 같은 기간원가는 제품 재고로 모으지 않고 해당 기간의 비용으로 처리해. 초급 문제는 제품원가인지 기간원가인지, 직접인지 간접인지 두 가지 질문을 각각 던져보면 좋아.')],
'“기본원가”는 재료+노무, “가공원가”는 노무+제조간접이야. 문제 옆에 세 원가를 따로 적고 필요한 두 항목만 묶어봐.')

chapter(12,[('조업도','생산수량·작업시간처럼 활동의 크기를 나타내는 수준.'),('변동원가','관련범위 안에서 조업도에 비례해 총액이 변하는 원가.'),('고정원가','관련범위 안에서 조업도가 달라도 총액이 일정한 원가.'),('혼합원가','고정원가 부분과 변동원가 부분을 함께 가진 원가.')],[
('총액과 개당 금액을 구분해','생산량이 바뀔 때 원가가 어떻게 움직이는지 살펴보자. 여기서 생산량이나 작업시간 같은 활동 수준을 조업도라고 해. 원가 문제는 총액을 물었는지, 제품 한 개당 원가를 물었는지에 따라 답이 달라져.\n개당 포장지 원가가 1,000원이라면 100개 생산할 때 포장지 총원가는 10만 원, 200개일 때는 20만 원이야. 단위당 금액은 같고 총액이 조업도에 비례해 변하는 것이 변동원가의 기본 모형이야.'),
('고정원가는 총액 기준이야','월 공장 임차료 60만 원이 일정한 범위에서 생산량과 관계없이 발생한다고 해보자. 100개 생산하면 개당 6,000원, 200개면 개당 3,000원이야. 고정원가 총액 60만 원은 같지만 단위당 고정원가는 줄었어.\n이 설명은 관련범위 안에서 성립해. 공장을 하나 더 빌려야 하는 수준으로 생산량이 커지면 고정원가 총액도 달라질 수 있어. 따라서 무한히 일정하다고 이해하면 안 돼.'),
('총원가 식을 읽는 법','Y = a + bX라는 식이 주어졌다면 Y는 총원가, X는 조업도, a는 고정원가 총액, b는 단위당 변동원가야. 숫자와 문자에 이름을 붙이면 식이 덜 낯설어져.\n고정원가 100만 원, 개당 변동원가 2,000원, 생산량 100개이면 총원가는 100만+20만=120만 원이야. 생산량을 곱해야 하는 것은 단위당 변동원가이고, 이미 총액인 고정원가에 다시 생산량을 곱하지 않아.'),
('혼합원가를 나눠 생각해','기본요금에 사용량 요금이 붙는 구조는 고정 부분과 변동 부분이 함께 있어. 이런 원가를 혼합원가라고 해. 기본요금을 a, 사용량당 요금을 b로 놓으면 앞의 총원가 식으로 표현할 수 있어.\n원가의 직접·간접 구분과 고정·변동 구분은 서로 다른 기준이야. 공장 임차료는 제품 관점에서 간접원가이면서 조업도 관점에서 고정원가일 수 있어. 한 비용에 분류 이름이 둘 붙어도 모순이 아니야.')],
'“단위당”이라는 말을 보면 총원가를 수량으로 나눈 값인지 확인해. 총고정원가와 단위당 고정원가의 움직임을 바꿔 외우지 않는 것이 핵심이야.')

chapter(13,[('재료','생산에 투입하기 전 보유한 원재료 등.'),('재공품','제조공정에 투입되어 아직 완성되지 않은 제품.'),('제품','제조를 완료해 판매할 수 있는 상태의 재고.'),('당기제품제조원가','당기에 완성되어 재공품에서 제품으로 이동하는 원가.')],[
('원가가 이동하는 네 단계','재료를 사서 창고에 보관한 단계와 재료를 공정에 투입한 단계는 달라. 생산에 투입하면 재료 원가가 재공품으로 이동하고, 작업자의 직접노무원가와 제조간접원가도 재공품에 모여.\n작업을 마치면 재공품의 완성 부분을 제품으로 옮겨. 그 제품을 판매하면 판매분의 원가를 매출원가로 옮겨. 재료→재공품→제품→매출원가의 순서를 먼저 익히면 여러 공식이 하나의 흐름으로 연결돼.'),
('당기총제조원가는 투입한 원가야','당기총제조원가는 이번 기간에 생산을 위해 투입한 직접재료·직접노무·제조간접원가의 합계야. 이번 기간에 투입했다고 모두 이번 기간에 완성되는 것은 아니야. 일부는 아직 만드는 중일 수 있어.\n지난 기간에 만들다 남은 원가는 기초재공품으로 넘어와. 기초재공품과 당기 투입원가를 합친 뒤 기말에도 미완성으로 남은 원가를 빼면, 당기에 완성한 원가가 돼.'),
('완성 원가 계산하기','당기제품제조원가 = 기초재공품 + 당기총제조원가 − 기말재공품이야. 기초 20, 당기투입 100, 기말미완성 30이면 20+100−30=90이 완성되어 제품으로 이동해.\n이때 빼는 30은 손실이 아니라 아직 공정에 남은 자산이야. “기말재공품이 증가했다”는 말은 같은 투입 조건이라면 완성품으로 옮겨 간 원가가 줄어든다는 의미로 연결돼.'),
('판매 원가까지 한 번 더 이동해','기초제품 + 당기제품제조원가에서 기말제품을 빼면 매출원가를 구할 수 있어. 기초제품 10, 당기완성 90, 기말제품 25이면 75가 판매분의 원가야.\n재공품과 제품은 둘 다 재고지만 완성 여부가 달라. 공식에서 기말재공품을 빼야 할 자리에 기말제품을 넣지 않도록 계정 이름을 끝까지 적어두자. 금액의 단위도 같은지 확인해.')],
'“총제조원가”는 당기 투입, “제품제조원가”는 당기 완성, “매출원가”는 판매야. 무엇을 물었는지에 따라 출발하는 재고 계정이 달라져.')

chapter(14,[('재료 사용액','기초재료와 당기 순매입액의 합계에서 기말재료를 뺀 금액.'),('직접재료','제품에 직접 추적하는 주요 제조용 재료.'),('간접재료','제조용이지만 제품에 직접 추적하지 않는 재료.'),('매입환출','구입한 재료나 상품을 매입처에 되돌려 보내는 것.')],[
('산 재료와 쓴 재료는 달라','창고에 있던 재료가 30만 원이고 이번 달에 100만 원을 샀다면 사용할 수 있었던 재료는 130만 원이야. 마지막에 20만 원이 남았다면 실제로 사용한 원가는 110만 원이야.\n이 관계를 기초재료+당기 순매입−기말재료라고 써. 앞에서 배운 재고 흐름과 같은 구조지만, 여기서는 판매원가가 아니라 재료 투입액을 구한다는 차이가 있어.'),
('순매입원가를 먼저 정리해','매입대가에 재료를 가져오는 매입운임을 더하고, 되돌려 보낸 재료의 금액인 매입환출 등을 빼면 순매입원가를 계산할 수 있어. 구입 금액 자체와 순매입원가가 같은지 먼저 확인해야 해.\n예를 들어 대가 200, 운임 5, 환출 15면 순매입원가는 190이야. 이 190을 재료 사용액 식의 당기 순매입액 자리에 넣는 거야. 판매 후 고객 배송비와 매입운임은 성격이 다르므로 구분해.'),
('직접재료를 한 번 더 분리해','총재료 사용액에 간접재료가 섞여 있을 수 있어. 총사용액 110 중 간접재료가 10이라면 직접재료는 100이야. 총사용액과 직접재료 사용액을 같은 값으로 놓으면 제조원가 집계에서 오류가 생길 수 있어.\n간접재료 10이 사라지는 것은 아니야. 제조간접원가 쪽에 들어가 제품에 배부돼. 직접재료에 전부 넣고 제조간접원가에도 간접재료를 더하면 같은 원가를 중복 계산하게 돼.'),
('장부에서 어디로 이동할까?','직접재료를 투입하면 재료 자산이 줄고 재공품 원가가 늘어. 간접재료를 사용하면 재료가 줄고 제조간접원가로 집계하는 흐름을 생각해.\n실제 매입·불출 단가 계산에는 선입선출법이나 평균법 등이 적용될 수 있어. 지금은 먼저 수량과 금액의 흐름을 익힌 다음, 여러 단가가 섞인 문제로 넘어가면 돼.')],
'재료 문제는 순매입 계산→총사용액 계산→간접재료 제외의 세 줄로 풀어. 문제에서 직접재료를 묻는지 총재료를 묻는지도 표시해.')

chapter(15,[('임률','노동시간 한 단위에 적용하는 임금률. 시간당 금액 등으로 표시해.'),('직접작업시간','특정 제품이나 주문에 직접 사용한 작업시간.'),('미지급급여','근로를 제공받았으나 아직 지급하지 않은 급여 의무.'),('간접노무원가','공장 감독자 급여처럼 제품에 직접 추적하지 않는 제조 관련 노동원가.')],[
('노동을 원가로 측정해','제조에 들어간 노동을 금액으로 나타내는 것이 노무원가야. 특정 제품에 직접 사용한 작업임금은 직접노무원가, 여러 제품을 돕는 공장 감독자의 급여 등은 간접노무원가로 분류할 수 있어.\n직접 작업시간 100시간에 시간당 임률 15,000원을 적용하면 150만 원이야. 시간과 금액 단위를 함께 적어보자. 시간당 금액에 작업시간을 곱하면 시간 단위가 사라지고 원 단위 금액이 남아.'),
('지급액이 발생액과 같을까?','이번 달 현금으로 준 급여에는 지난달 밀린 급여가 포함될 수 있어. 반대로 이번 달 일한 급여 일부를 아직 주지 않았을 수도 있어. 그래서 당기 발생액을 구할 때는 지급액만 보면 안 돼.\n발생액 = 지급액 + 기말미지급 − 기초미지급이야. 기말미지급은 이번 기간에 일했지만 아직 못 준 부분이라 더하고, 기초미지급은 전 기간에 발생한 부분이므로 이번 기간 발생액에서 빼는 거야.'),
('숫자로 기간을 맞춰보자','지급액 100, 기초미지급 10, 기말미지급 20이면 발생액은 110이야. 이번 달 지급 100 중 전월분 10을 빼면 90, 여기에 이번 달분 미지급 20을 더하면 110이 되는 거지.\n지급액을 거꾸로 묻는다면 지급액 = 발생액 + 기초미지급 − 기말미지급으로 정리할 수 있어. 외우기 어렵다면 원래 식에 숫자를 넣고 모르는 값을 찾으면 돼.'),
('총액에서 직접 부분을 구해','공장 노무원가 총액 200 중 간접노무가 50이면 직접노무는 150이야. 다만 판매사원이나 본사 직원 급여는 제조노무원가에 섞으면 안 돼. 어떤 부서에서 어떤 업무에 사용한 노동인지 확인해.\n작업 A 40시간, B 60시간, 시간당 2만 원이라면 A 직접노무 80, B 120으로 연결돼. 제품마다 시간을 따로 추적했다는 점이 직접노무의 의미야.')],
'“지급”, “발생”, “기초미지급”, “기말미지급”은 다른 말이야. 먼저 어느 기간 근로에 대한 돈인지 적고 계산해.')

chapter(16,[('배부기준','공통 원가를 제품이나 작업에 나눌 때 사용하는 합리적인 기준.'),('예정배부율','예상 제조간접원가를 예상 배부기준 총량으로 나눈 비율.'),('과소배부','실제 발생한 제조간접원가보다 배부한 금액이 적은 상태.'),('과대배부','실제 발생한 제조간접원가보다 배부한 금액이 많은 상태.')],[
('공통 원가를 어떻게 나눌까?','공장 전기료처럼 여러 제품이 함께 사용한 원가는 제품 A에 정확히 얼마가 들었는지 바로 추적하기 어려워. 이런 공통 원가를 일정한 기준으로 나눠 주는 과정을 배부라고 해.\n기계를 많이 쓴 제품이 전기를 더 사용한다면 기계작업시간이 배부기준이 될 수 있어. 노동 중심 공정에서는 직접노무시간 등을 쓸 수도 있어. 아무 숫자나 고르기보다 원가 발생과 관련 있는 기준을 선택하는 것이 중요해.'),
('기간 전에 나눌 비율을 정해','실제 월말 전기료 등을 기다려야만 제품원가를 계산할 수 있다면 처리가 늦어질 수 있어. 그래서 예상 제조간접원가와 예상 조업도로 미리 예정배부율을 정할 수 있어.\n예상 간접원가 100만 원, 예상 기계시간 500시간이면 시간당 2,000원이야. 이때 분모는 아직 기간 전에 정하는 예상시간이야. 실제시간과 섞지 않아.'),
('실제 사용량에 비율을 적용해','작업 A가 실제로 20시간 사용했다면 예정배부액은 2,000×20 = 4만 원이야. 배부율을 정할 때는 예상량을 썼지만, 각 작업에 적용할 때는 그 작업이 실제로 사용한 기준량을 곱해.\n직접노무원가의 150%처럼 비율로 줄 때도 구조는 같아. A의 실제 직접노무원가가 40이면 40×1.5=60을 배부해. 150%는 150을 그대로 곱하는 게 아니라 1.5라는 뜻이야.'),
('실제 발생액과 비교해','실제 간접원가 120, 배부액 100이라면 20을 적게 배부했으므로 과소배부야. 반대로 실제 90, 배부 100이면 10을 많이 배부한 과대배부야. 부족과 초과를 일상어로 먼저 읽으면 이름이 덜 헷갈려.\n과소배부 20 전액을 매출원가에 조정하라는 조건이면 매출원가에 20을 더해. 과대배부를 전액 조정하면 매출원가에서 빼는 방향이지. 재고까지 나누어 조정하는 조건이면 배분 대상과 기준을 따로 읽어야 해.')],
'분모는 예상 총량, 곱하는 값은 작업의 실제량이야. 차이는 실제액−배부액으로 계산한 뒤 실제가 더 큰지 작은지를 말로 확인해.')

chapter(17,[('제조부문','제품의 생산 작업을 직접 수행하는 부문.'),('보조부문','수선·동력 등으로 다른 부문의 생산 활동을 지원하는 부문.'),('직접배분법','보조부문 사이 상호 서비스를 무시하고 제조부문에만 원가를 배분하는 방법.'),('상호배분법','보조부문끼리 주고받은 서비스까지 반영해 원가를 배분하는 방법.')],[
('제품 전에 부문을 거칠 수 있어','공장에는 제품을 직접 만드는 제조부문과, 수선실처럼 생산을 지원하는 보조부문이 있을 수 있어. 공통 원가를 먼저 부문별로 모으고, 보조부문의 원가를 제조부문에 배분한 뒤 제품에 나눌 수 있어.\n예를 들어 수선부가 제조 A와 B에 서비스를 제공했다면 그 수선 원가도 A·B 제품의 제조원가에 반영되어야 해. 서비스를 받은 시간 같은 기준이 부문 배분에 사용될 수 있어.'),
('직접배분법의 분모','직접배분법은 보조부문끼리 주고받은 서비스를 무시하고 제조부문으로만 나누는 방법이야. 따라서 배분 비율의 분모에도 제조부문 이용량만 넣어.\n수선부 원가 60, 제조 A 이용시간 100, B 200이면 A에 60×100/300=20, B에 40을 배분해. 다른 보조부문에 제공한 100시간이 있더라도 직접배분법에서는 이 분모에 넣지 않아.'),
('단계배분과 상호배분','단계배분법은 순서를 정해 배분하고, 먼저 배분을 끝낸 보조부문으로 다시 되돌려 주지 않는 방법이야. 어느 부문을 먼저 배분하라는 조건이 중요해져.\n상호배분법은 보조부문 간 상호 서비스까지 반영해. 서로 영향을 주기 때문에 연립방정식으로 총원가를 구하는 방식 등을 사용할 수 있어. 직접배분법보다 고려하는 관계가 많다는 차이를 먼저 이해하자.'),
('제조부문 총액에서 제품 배부로','제조 A 자체 원가가 40이고 보조부문에서 20을 배분받았다면 A에 집계된 원가는 60이야. 이후 이 60을 제품에 배부할 기준과 조업도를 적용할 수 있어.\n보조부문 원가 배분과 제조간접원가의 제품 배부는 이어지는 과정이지만 계산 단계는 달라. 문제에 제시된 표에서 어느 부문 원가를 묻는지, 제품의 배부액을 묻는지 구분해.')],
'직접배분법에서는 보조부문끼리의 이용량을 지우고 제조부문 이용량만 더해봐. 단계배분법은 배분 순서를 화살표로 적으면 도움이 돼.')

chapter(18,[('개별원가계산','작업이나 주문별로 제조원가를 따로 모아 계산하는 방법.'),('작업원가표','특정 작업의 직접재료·직접노무·배부 제조간접원가를 집계하는 자료.'),('작업 총원가','그 작업에 직접 추적하거나 배부한 제조원가의 합계.'),('단위원가','제품 한 단위에 해당하는 원가로, 총원가를 해당 수량으로 나눈 값.')],[
('주문마다 다른 제품을 만들면','맞춤 가구처럼 주문 A와 B의 규격·재료·작업량이 다르면 두 주문의 원가를 따로 모으는 것이 유용해. 개별원가계산은 작업이나 주문을 원가 집계의 기본 단위로 삼는 방법이야.\n주문별 작업원가표에 직접재료와 직접노무를 추적하고, 공장 공통 원가는 정한 배부기준으로 나눠 기록해. 모든 주문의 원가를 무조건 평균내는 것과 달라.'),
('직접 원가에 배부 원가를 더해','작업 A에 재료 50, 노무 30, 배부 간접원가 20이 들었다면 총원가는 100이야. 간접원가가 실제액인지 예정배부액인지 문제 조건을 확인해.\n노무원가의 150%를 배부하라고 하고 실제 노무원가가 40이면 간접원가는 60이야. 작업원가 전체를 구할 때는 직접재료와 직접노무를 이 60에 더해야 해. 배부액만을 작업 총원가로 착각하지 않아야 해.'),
('한 개당 원가로 나눠','총원가 120만 원으로 60개를 만들었다면 단위원가는 120/60=2만 원이야. 총원가를 수량으로 나누는 과정이고, 판매가격이나 매출액으로 나누는 것이 아니야.\n같은 단위원가의 완성품 60개 중 40개를 판매했다면 판매된 원가는 80만 원, 남은 제품원가는 40만 원이야. 생산수량과 판매수량을 각각 적어두면 구분하기 쉬워.'),
('미완성 주문은 재공품에 남아','기말에 작업 A 30, B 50이 아직 미완성이면 기말재공품은 80이야. 완성한 C 80이 따로 있어도 C는 제품으로 이동했으므로 이 재공품 합계에는 포함하지 않아.\n완성 후 아직 안 판 것과 아직 완성하지 못한 것은 서로 다른 상태야. 문제 표의 완성 여부와 판매 여부를 따로 표시한 뒤 원가를 재공품·제품·매출원가로 나눠보자.')],
'개별원가계산은 주문별 세 원가를 먼저 더하고 완성·판매 여부를 판단해. 미완성 주문 합계는 기말재공품이라는 연결을 기억해.')

chapter(19,[('종합원가계산','동종 제품을 연속 생산하는 공정에서 공정별 원가를 모아 평균 계산하는 방법.'),('완성도','해당 원가 요소의 투입 또는 작업이 얼마나 진행됐는지를 나타내는 비율.'),('완성품환산량','미완성품 작업량을 완성품 기준의 수량으로 환산한 값.'),('평균법','기초재공품 원가와 당기 투입원가를 합쳐 평균 단가를 계산하는 방법.')],[
('같은 제품을 계속 만들면','같은 규격의 음료나 시멘트를 연속으로 생산한다면 주문별로 나누기보다 공정 전체의 원가를 모아 계산할 수 있어. 이것이 종합원가계산이야.\n문제는 기말에 덜 완성된 재공품이 남을 수 있다는 거야. 완성품 1개와 절반만 작업한 재공품 1개에 무조건 같은 원가를 주면 공정의 작업량 차이를 반영하지 못해.'),
('절반 완성 두 개는 한 개 분량','가공완성도 50%인 재공품 20개는 완성품 10개에 해당하는 가공 작업량이야. 이 10개를 완성품환산량이라고 해. 재공품 실물 수량 20개가 사라지는 것이 아니라 원가 배분용 작업량 단위로 바꾼 거야.\n평균법에서 완성 100개, 기말재공품 20개, 가공완성도 50%이면 가공 환산량은 100+10=110개야. 이 환산량으로 가공원가 총액을 나눠 단가를 구할 수 있어.'),
('재료와 가공을 따로 계산하는 이유','재료를 공정 초기에 전량 투입했다면 공정에 들어온 기말재공품은 가공이 절반이어도 재료 기준으로는 100% 투입된 상태야. 그래서 재료 환산량과 가공 환산량을 따로 계산해.\n기말재공품 20개, 재료 단가 2만 원, 가공 단가 1만 원, 가공완성도 50%라면 재료원가 40만 원과 가공원가 10만 원을 합해 50만 원이야. 가공완성도 50%를 재료에도 똑같이 적용하지 않아.'),
('평균법과 선입선출법','평균법은 기초재공품 원가와 당기 원가를 합쳐 평균내는 방법이야. 선입선출법은 기초재공품에 전기에 이미 투입한 부분을 구분하고 당기에 수행한 작업량을 따로 계산해.\n기초재공품 20개가 이미 40% 가공됐다면 당기에 이 기초품을 완성하는 데 필요한 가공 작업량은 20×60%=12개 분량이야. 실물 수량 흐름에서는 기초+당기착수−완성=기말을 먼저 맞춰보고, 다음에 방법별 환산량을 계산해.')],
'실물 수량과 환산량을 섞지 마. 수량 흐름을 맞춘 다음 재료·가공 두 줄로 나누고, 평균법인지 선입선출법인지 확인해.')

chapter(20,[('결합원가','여러 결합제품이 분리되기 전 공통 공정에서 함께 발생한 원가.'),('분리점','함께 생산된 제품을 개별 제품으로 식별할 수 있게 되는 지점.'),('물량기준법','제품의 수량·중량 등 물량 비율을 기준으로 결합원가를 배분하는 방법.'),('매몰원가','이미 발생해 현재 선택으로 바꿀 수 없고 회수할 수 없는 원가.')],[
('하나의 공정에서 여러 제품이 나와','정유 공정처럼 하나의 공통 공정에서 여러 제품이 함께 나올 수 있어. 개별 제품으로 식별할 수 있게 되는 지점을 분리점, 그 전까지 공통으로 발생한 원가를 결합원가라고 해.\n분리점 이후 특정 제품을 더 가공하기 위해 드는 원가는 그 제품의 추가가공원가야. 공통 원가와 제품별 후속 원가가 발생하는 구간부터 나누면 계산이 정리돼.'),
('결합원가를 비율로 나눠','물량기준법은 제품의 수량이나 중량 비율을 사용해. 공통 원가 100, A 300kg, B 200kg이면 B에 100×200/500=40을 배분해. 비교 가능한 같은 단위의 물량인지도 확인해야 해.\n상대적 판매가치법은 물량 대신 분리점 판매가치 비율을 사용해. 공통 원가 90, A 판매가치 200, B 100이면 A 60, B 30이야. 제품별 단가만이 아니라 전체 판매가치를 사용한다는 점을 읽어.'),
('추가가공은 새로 달라지는 부분을 봐','지금 팔면 50, 추가가공 후 팔면 80, 추가가공비가 20이면 매출이 30 늘고 원가가 20 늘어. 따라서 추가가공으로 이익은 10 증가해. 다른 제약이 없다면 추가가공이 유리해.\n이 판단에서는 이미 발생한 공통 결합원가를 다시 더하지 않아. 지금 어떤 선택을 해도 바꿀 수 없는 매몰원가이기 때문이야. 재고 원가 배분과 미래 의사결정은 목적이 다르다는 점을 구분해야 해.'),
('계산 결과를 말로 점검해','추가수익 15, 추가원가 20이면 추가가공할수록 이익이 5 줄어. 생산을 더 했다는 이유만으로 항상 이익이 커지는 것은 아니야. 늘어나는 수익과 비용을 비교해야 해.\n원가 배분 비율은 분자가 전체 분모보다 작거나 같으므로 각 배분액은 일반적으로 배분 대상 총원가를 넘지 않아야 해. A와 B에 나눈 금액을 합해 원래 결합원가와 맞는지 점검해보자.')],
'배분 문제는 공통 원가×내 몫 비율, 추가가공 판단은 추가수익−추가원가야. 둘은 같은 식이 아니므로 문제의 목적부터 구분해.')

def numeric(lid, n):
    """Four explicitly labelled numeric repetitions per chapter, with worked steps."""
    k=n+1
    if lid==1:
        own=300+100*k; debt=50*k; ans=own+debt; unit='만 원'
        prompt=f'새 상황: 내 돈 {own}만 원과 은행에서 빌린 {debt}만 원을 회사 통장에 넣었다. 현재 총자산은?'
        steps=[f'내가 낸 돈 {own}만 원은 통장 자산을 늘려.',f'빌린 {debt}만 원도 지금 보유하므로 자산에 포함해.',f'{own} + {debt} = {ans}만 원. 부채는 {debt}, 자본은 {own}만 원이야.']
    elif lid==2:
        a=20*k;b=10*(k+1);ans=a+b;unit='만 원'
        prompt=f'새 상황: 한 거래의 차변에 현금 {a}만 원과 비품 {b}만 원을 적었다. 대변 금액의 합계는?'
        steps=[f'차변에 두 자산이 있어: 현금 {a}, 비품 {b}.',f'차변 합계는 {a}+{b}={ans}만 원이야.',f'차변과 대변 합계가 같아야 하므로 대변 합계도 {ans}만 원이야.']
    elif lid==3:
        annual=120*k;months=k+2;ans=annual//12*months;unit='만 원'
        prompt=f'새 상황: 1년분 보험료 {annual}만 원을 선급했다. 결산일까지 {months}개월을 사용했다면 당기 보험료는? 월할 계산한다.'
        steps=[f'월 보험료 = {annual}÷12={annual//12}만 원.',f'사용한 기간 {months}개월분만 당기 비용이야.',f'{annual//12}×{months}={ans}만 원. 미사용분은 선급비용으로 남겨.']
    elif lid==4:
        total=500*k;rate=2;prior=3*k;ans=total*rate//100-prior;unit='만 원'
        prompt=f'새 상황: 채권 {total}만 원에 손실률 2%를 단순 적용한다. 조정 전 충당금 대변잔액은 {prior}만 원이다. 추가 설정액은?'
        steps=[f'필요 충당금 = {total}×2%={total*rate//100}만 원.',f'이미 있는 대변잔액 {prior}만 원을 빼.',f'{total*rate//100}−{prior}={ans}만 원을 추가 설정해.']
    elif lid==5:
        start=50*k;buy=200*k;end=30*k;ans=start+buy-end;unit='만 원'
        prompt=f'새 상황: 기초 상품 {start}, 당기 순매입 {buy}, 기말 상품 {end}이다. 매출원가는? 단위: 만 원.'
        steps=[f'판매 가능한 원가 = 기초 {start}+순매입 {buy}={start+buy}.',f'아직 남은 기말재고 {end}는 판매원가에서 빼.',f'{start+buy}−{end}={ans}만 원이 매출원가야.']
    elif lid==6:
        cost=600*k;res=60*k;years=6;ans=(cost-res)//years;unit='만 원'
        prompt=f'새 상황: 기계 원가 {cost}, 잔존가치 {res}, 내용연수 6년이다. 연초부터 사용한 정액법 1년 상각비는? 단위: 만 원.'
        steps=[f'나눌 금액 = 원가 {cost}−잔존가치 {res}={cost-res}.','이 금액을 6년에 똑같이 나눠.',f'{cost-res}÷6={ans}만 원이 연간 상각비야.']
    elif lid==7:
        future=110*k;ans=100*k;unit='만 원'
        prompt=f'새 상황: 1년 뒤 받을 {future}만 원을 연 10%로 할인한다. 현재가치는?'
        steps=['1년 뒤 금액을 지금 가치로 바꾸려면 이자율을 거꾸로 적용해.','1+10%=1.1로 나눠.',f'{future}÷1.1={ans}만 원이야.']
    elif lid==8:
        carrying=200*k;rate=5;ans=10*k;unit='만 원'
        prompt=f'새 상황: 사채 기초 장부금액 {carrying}만 원, 연 유효이자율 5%다. 중간 변동 없이 1년 유효이자비용은?'
        steps=[f'비용 계산 기준은 액면이 아니라 기초 장부금액 {carrying}이야.','5%를 0.05로 바꿔 곱해.',f'{carrying}×0.05={ans}만 원이야.']
    elif lid==9:
        par=5000;price=6000+1000*k;shares=100;ans=(price-par)*shares//10000;unit='만 원'
        prompt=f'새 상황: 액면 5,000원인 100주를 주당 {price:,}원에 발행했다. 주식발행초과금은? 발행비용은 없다.'
        steps=[f'한 주당 액면 초과액 = {price:,}−5,000={price-par:,}원.',f'100주 전체 초과액 = {price-par:,}×100={(price-par)*100:,}원.',f'원 단위를 만 원으로 바꾸면 {ans}만 원이야.']
    elif lid==10:
        profit=100*k;dep=20*k;ar=5*k;ans=profit+dep-ar;unit='만 원'
        prompt=f'새 상황: 순이익 {profit}, 감가상각비 {dep}, 매출채권 증가 {ar}이다. 다른 조정이 없을 때 간접법 영업현금흐름은? 단위: 만 원.'
        steps=[f'순이익 {profit}에서 출발해.',f'비현금 비용인 상각비 {dep}를 더하고, 아직 못 받은 채권 증가 {ar}를 빼.',f'{profit}+{dep}−{ar}={ans}만 원이야.']
    elif lid==11:
        labor=30*k;over=20*k;ans=labor+over;unit='만 원'
        prompt=f'새 상황: 직접재료 {80*k}, 직접노무 {labor}, 제조간접 {over}이다. 가공원가는? 단위: 만 원.'
        steps=['가공원가는 재료를 제품으로 만드는 노무와 제조간접원가야.',f'직접재료 {80*k}는 이번 합계에 넣지 않아.',f'직접노무 {labor}+제조간접 {over}={ans}만 원이야.']
    elif lid==12:
        fixed=600000*k;units=100*k;ans=fixed//units;unit='원'
        prompt=f'새 상황: 관련범위 안에서 고정원가 총액 {fixed:,}원, 생산량 {units}개다. 단위당 고정원가는?'
        steps=[f'총액 {fixed:,}원을 제품 {units}개에 나눠.',f'단위당 = 총고정원가÷생산량이야.',f'{fixed:,}÷{units}={ans:,}원/개야.']
    elif lid==13:
        start=20*k;inp=100*k;end=30*k;ans=start+inp-end;unit='만 원'
        prompt=f'새 상황: 기초재공품 {start}, 당기총제조원가 {inp}, 기말재공품 {end}이다. 당기 완성품 제조원가는? 단위: 만 원.'
        steps=[f'완성 가능한 원가 합계 = 기초 {start}+당기투입 {inp}={start+inp}.',f'기말 미완성 {end}는 재공품에 남겨.',f'{start+inp}−{end}={ans}만 원이 완성돼 제품으로 이동해.']
    elif lid==14:
        start=30*k;buy=150*k;end=20*k;ind=10*k;ans=start+buy-end-ind;unit='만 원'
        prompt=f'새 상황: 기초재료 {start}, 순매입 {buy}, 기말재료 {end}, 간접재료 사용 {ind}이다. 직접재료 사용액은? 단위: 만 원.'
        steps=[f'총사용액 = {start}+{buy}−{end}={start+buy-end}.',f'총사용액에는 간접재료 {ind}도 포함돼 있어.',f'{start+buy-end}−{ind}={ans}만 원이 직접재료야.']
    elif lid==15:
        paid=100*k;begin=10*k;end=30*k;ans=paid+end-begin;unit='만 원'
        prompt=f'새 상황: 공장 급여 지급 {paid}, 기초미지급 {begin}, 기말미지급 {end}이다. 당기 발생 노무원가는? 단위: 만 원.'
        steps=[f'지급 {paid}에서 전기분 기초미지급 {begin}를 빼.',f'이번 기간 일했지만 아직 안 준 기말미지급 {end}를 더해.',f'{paid}−{begin}+{end}={ans}만 원이 당기 발생액이야.']
    elif lid==16:
        expected=1000000*k;hours=500;used=10+k;ans=expected//hours*used;unit='원'
        prompt=f'새 상황: 예상 제조간접원가 {expected:,}원, 예상 기계시간 500시간, A의 실제 사용 {used}시간이다. A 예정배부액은?'
        steps=[f'시간당 예정배부율 = {expected:,}÷500={expected//hours:,}원.',f'A가 실제로 사용한 {used}시간을 곱해.',f'{expected//hours:,}×{used}={ans:,}원이야.']
    elif lid==17:
        total=60*k;a=100;b=200;ans=total*a//(a+b);unit='만 원'
        prompt=f'새 상황: 보조부 원가 {total}만 원, 제조 A 사용 100시간, B 200시간이다. 직접배분법으로 A에 배분할 금액은?'
        steps=['직접배분법은 제조부문 사용량만 더해 분모로 써.','A 비율 = 100÷(100+200)=1/3이야.',f'{total}×1/3={ans}만 원이 A의 몫이야.']
    elif lid==18:
        mat=50*k;lab=20*k;over=30*k;ans=mat+lab+over;unit='만 원'
        prompt=f'새 상황: 주문 A 직접재료 {mat}, 직접노무 {lab}, 배부 제조간접원가 {over}이다. A 작업 총원가는? 단위: 만 원.'
        steps=[f'해당 주문에 직접 추적한 재료 {mat}와 노무 {lab}를 적어.',f'배부한 공통 제조간접원가 {over}도 포함해.',f'{mat}+{lab}+{over}={ans}만 원이 주문 A의 총원가야.']
    elif lid==19:
        done=100*k;wip=20*k;ans=done+wip//2;unit='개'
        prompt=f'새 상황: 평균법, 완성품 {done}개, 기말재공품 {wip}개, 가공완성도 50%다. 가공원가 완성품환산량은?'
        steps=[f'완성품 {done}개는 가공이 100% 끝났어.',f'기말재공품 작업량 = {wip}×50%={wip//2}개 분량.',f'{done}+{wip//2}={ans}개가 가공 환산량이야.']
    else:
        total=90*k;va=200;vb=100;ans=total*va//(va+vb);unit='만 원'
        prompt=f'새 상황: 결합원가 {total}만 원, 분리점 판매가치 A 200만 원, B 100만 원이다. 상대적 판매가치법으로 A에 배분할 금액은?'
        steps=['배분기준은 수량이 아니라 각 제품의 전체 판매가치야.','A 비율 = 200÷(200+100)=2/3이야.',f'{total}×2/3={ans}만 원을 A에 배분해.']
    choices=[f'{ans:,}{unit}',f'{ans+7:,}{unit}',f'{max(0,ans-3):,}{unit}',f'{ans*2+1:,}{unit}']
    assert len(set(choices))==4
    return dict(prompt=prompt,choices=choices,correct=0,explanation=' → '.join(steps),steps=steps)

books[1]['sections'].insert(0,dict(title='금액과 계산 기호부터 읽어보자',paragraphs=[
    '문제에서 ￦ 또는 ₩는 원화를 뜻해. ￦100,000은 100,000원이고 10만 원이야. 쉼표는 큰 수를 읽기 쉽게 끊는 표시라 계산할 때 금액의 값이 달라지는 것은 아니야. 1만 원은 10,000원, 100만 원은 1,000,000원이야. 문제에 “단위: 만 원”이라고 쓰여 있으면 표의 100은 100원이 아니라 100만 원을 뜻해.',
    '×는 곱하기, ÷는 나누기, %는 백분율이야. 10%는 100분의 10, 즉 0.1이므로 100만 원의 10%는 10만 원이야. 50%는 절반인 0.5, 150%는 1.5배야. 서로 다른 금액 단위를 한 식에 섞지 말고 원 또는 만 원 중 하나로 맞춘 뒤 계산해.'
]))
books[3]['sections'].insert(0,dict(title='수익과 비용은 무슨 뜻일까?',paragraphs=[
    '카페가 손님에게 커피를 제공해 대가를 받을 권리를 얻었다면 영업 성과인 매출수익을 생각할 수 있어. 수익은 자산 증가나 부채 감소를 통해 자본을 늘리는 성과이지만 주주의 출자는 제외해. 통장에 돈이 들어왔다는 사실만으로 매출이 되는 것이 아니라 무엇을 제공해 벌었는지 봐야 해.',
    '비용은 수익을 얻기 위한 활동 등에서 자원을 사용해 자산이 감소하거나 의무가 생기면서 자본이 줄어드는 항목이야. 사용한 기간의 임차료·급여·보험료 등을 생각해. 주주에게 나눠주는 배당은 비용이 아니야. 또한 여러 해 사용할 기계를 현금으로 샀다면 우선 현금이 기계라는 자산으로 바뀐 것이므로 구입대금 전체를 즉시 비용이라고 생각하지 않아야 해.'
]))

for lesson in data['lessons']:
    lid=lesson['id'];book=books[lid]
    lesson['book']=book
    for n,term in enumerate(book['terms']):
        others=[t['meaning'] for t in book['terms'] if t!=term]
        data['questions'].append(dict(id=f'{lid:02}-B{n+1}',lesson=lid,subject=lesson['subject'],level='입문',kind='자체 제작',prompt=f'입문 용어 확인: ‘{term["word"]}’의 뜻으로 알맞은 것은?',choices=[term['meaning']]+others,correct=0,explanation=f'{term["word"]}: {term["meaning"]} 이 뜻을 먼저 말로 설명한 다음 계산 문제로 넘어가면 돼.'))
    for n in range(4):
        q=numeric(lid,n)
        if n==0:book['worked']=q
        data['questions'].append(dict(id=f'{lid:02}-N{n+1}',lesson=lid,subject=lesson['subject'],level='반복',kind='자체 제작 · 숫자 반복',**q))
    lesson['questionCount']=sum(q['lesson']==lid for q in data['questions'])

data['questions'].sort(key=lambda q:(q['lesson'],{'입문':0,'기초':1,'응용':2,'반복':3}[q['level']],q['id']))
assert len(books)==20 and len(data['questions'])==320
assert len({q['id'] for q in data['questions']})==320
assert len({q['prompt'] for q in data['questions']})==320
(root/'content.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
print('Expanded: 20 textbook chapters / 80 terminology + 160 existing + 80 numeric repetition questions')
